"""Build an offline guided presentation from this completed run's actual records."""
from pathlib import Path
import json
import html
from urllib.parse import quote

P=Path(__file__).resolve().parent
R=P.parents[1]
OUT='../../artifacts/final_outcome/kite-core-demo/'
CTX='../../.context/kite-core-demo/'
def esc(s):return html.escape(str(s))
def link(path,label):return f'<a href="{esc(path)}" target="_blank" rel="noopener">{esc(label)} ↗</a>'
def receipt(path,label='Open the record'):
    return f'<details><summary>{esc(label)}</summary><pre>{esc((P/path).read_text())}</pre></details>'
def figure(path,label):return f'<figure><img src="{esc(path)}" alt="{esc(label)}"><figcaption>{esc(label)}</figcaption></figure>'
def section(n,title,time,body,say):
    return f'<section id="stage-{n}" class="stage" {"" if n==1 else "hidden"}><div class="eyebrow">STAGE {n} / 8 · {time}</div><h1>{title}</h1>{body}<aside class="say"><b>SAY</b><span>{esc(say)}</span></aside></section>'

verification=json.loads((R/'artifacts/final_outcome/kite-core-demo/verification.json').read_text())
refs=json.loads((P/'references/manifest.json').read_text())
route=json.loads((P/'shot-routing.json').read_text())
sections=[]
sections.append(section(1,'One sentence starts the run.','0:00–0:20',
    '<blockquote>Make a short Kite.ai launch video showing release notes becoming a draft launch page, then improving through feedback.</blockquote><p class="lead">Standing instructions supply research, shot routing, review, assembly and delivery checks.</p><div class="chips"><span>30-second film</span><span>Core workflow</span><span>$10 ceiling</span></div><p class="small">Example sentence chosen by the agent for this run. No Phase 2 movement research.</p>'+link('BRIEF.md','Open the brief'),
    'I start with one sentence; the standing workflow handles the production steps.'))
cards=[]
for i,(ref,title,lesson,start,end) in enumerate(zip(refs['selection'],['Motion-5 · actual Grok Bot story','Cero','Paper'],['One request → visible work','Physical opening → exact UI','Focus on one readable interaction'],[10,1,6],[14,4,9]),1):
    src='../../data/library/'+quote(ref['name'])
    cards.append(f'<article class="ref"><h2>{title}</h2><video id="ref-{i}" controls preload="metadata" poster="references/0{i}-{ref["genre"]}.jpg" src="{src}"></video><p>{lesson}</p><button class="excerpt" data-video="ref-{i}" data-start="{start}" data-end="{end}">Play {start}–{end}s excerpt</button></article>')
sections.append(section(2,'References before the plan.','0:20–0:55','<div class="grid three">'+''.join(cards)+'</div><p class="small">Actual general library: '+esc(refs['library'])+' · 11 files; 3 selected. Chronological decoded samples and closer joins reviewed. General reference gate passed.</p>'+link('reference-review.json','Review findings')+' · '+link('references/manifest.json','Source inventory'),
    'It studies relevant examples before planning, using our general video library.'))
rows=''.join(f'<tr><td>{s["time"]}s</td><td>{esc(s["purpose"])}</td><td>{"Generated still life" if s["id"]=="S01" else "Authored UI / text"}</td></tr>' for s in route['shots'])
sections.append(section(3,'Five shots. One connected story.','0:55–1:25','<table><thead><tr><th>Time</th><th>Purpose</th><th>Visual</th></tr></thead><tbody>'+rows+'</tbody></table><p class="lead">The same fictional Relay release carries through the request, draft and revision.</p>'+link('STORYBOARD.md','Detailed shot plan'),
    'Each shot has a purpose, a plan, and a review criterion.'))
sections.append(section(4,'Choose the method per shot.','1:25–1:55','<div class="grid two"><article><div class="eyebrow">S01 · 0–4s</div><h2>Cinematic paper</h2><p>Kling 3 Pro · Fal · silent T2V</p><p>One 5-second candidate, then review. Estimated $0.56; $0.65 reserved.</p></article><article><div class="eyebrow">S02–S05 · 4–30s</div><h2>Readable product story</h2><p>HyperFrames · HTML / CSS / GSAP</p><p>Exact copy, interaction states, timing, brand and final CTA.</p></article></div><p class="small">No compatible paper T2V endorsement existed before the test. A provider default was not treated as a universal routing rule.</p>'+link('shot-routing.json','Routing evidence')+' · '+link('generation-plan.json','Exact prompt and settings'),
    'The shot determines the method; accurate text is rendered deterministically.'))
sections.append(section(5,'Review changes the result.','1:55–2:40','<div class="grid two"><article><h2>Generated take: accepted</h2><video controls preload="metadata" src="assets/paper-opening.mp4"></video><p class="small">One paid take. Whole 5s sampled chronologically; first 4s used. No paid rejection or retry.</p></article><article><h2>Assembly: revised</h2>'+figure(CTX+'snapshots-01/frame-00-at-1s.png','Before: opening headline hidden behind footage')+figure(CTX+'snapshots-final/frame-00-at-1.5s.png','After: headline visible; correct Latin font')+'</article></div>'+link('generation-review.json','Shot decision')+' · '+link('composition-revisions.json','Actual revision history'),
    'The generated take passed, but the first assembly did not; review caught a hidden headline and a wrong font subset.'))
sections.append(section(6,'Past results inform the next decision.','2:40–3:10','<div class="grid two"><article><h2>Applied from earlier work</h2><ul><li>Fold: preserve the same facts from input to result.</li><li>Fold: show a second action changing the result.</li><li>Fold failure: avoid stretching live text during a surface change.</li><li>Crumb: stationary object + one camera direction supports a small candidate test.</li></ul></article><article><h2>New evidence saved</h2><p class="mono">kite_core_paper_v1</p><p><strong>selected</strong> → compatible future product-shot evidence.</p><p class="small">One subjective reviewed sample gives a provisional recommendation, not a universal best-model claim.</p></article></div>'+link('LEARNINGS.md','Prior learning receipts')+' · '+link('learning-after-run.json','Refreshed recommendation'),
    'Past results influence this run, and this reviewed result becomes evidence for the next one.'))
sections.append(section(7,'The finished film.','3:10–3:50',f'<video id="final-video" class="final" controls preload="metadata" poster="{CTX}encoded/poster.png" src="{OUT}kite-core-demo.mp4"></video><div class="chips"><span>30.0s · 1080p · 30fps</span><span>900 frames decoded</span><span>42/42 contrast checks</span><span>Audio verified numerically</span></div><p>'+link(OUT+'kite-core-demo.mp4','Open MP4')+' · '+link(OUT+'verification.json','Final checks')+'</p>',
    'Here is the finished 30-second film.'))
doc=R/'artifacts/final_outcome/kite-core-demo/kite-core-demo.reverse-engineering.md'
head='\n'.join(doc.read_text().splitlines()[:6])
sections.append(section(8,'One video. Its own production record.','3:50–4:40','<div class="grid two"><article><h2>Beside the final MP4</h2><pre>'+esc(head)+'</pre><p>Structure · exact prompts · models/methods · routing · revisions · failures · learnings</p>'+link(OUT+doc.name,'Individual reverse-engineering MD')+'</article><article><h2>The completion gate</h2><div class="failed"><b>Before the document existed</b><p>'+esc((P/'document-gate-before.txt').read_text())+'</p></div><div class="passed"><b>After it was written</b><p>Passed: individual file, required sections and matching video SHA-256.</p></div>'+link('document-gate-after.json','Actual passed gate')+'</article></div><p class="small">The completed delivery manifest includes this document’s path and hash. A combined project report does not satisfy the gate.</p>'+link('DEMO_LOG.md','Full demo log')+' · '+link('FIVE_MINUTE_DEMO.md','Timed speaking notes')+' · '+link('TOOLING_NOTE.md','Tooling intervention'),
    'This video stays incomplete until its own production document exists and matches the final file.'))

nav=''.join(f'<button data-stage="{i}" class="nav-item {"active" if i==1 else ""}"><span>0{i}</span>{label}</button>' for i,label in enumerate(['Request','References','Shot plan','Routing','Generation + review','Learnings','Final video','Production record'],1))
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kite · Core workflow demo</title><style>
@font-face{font-family:Onest;src:url('assets/Onest.woff2');font-weight:100 900}*{box-sizing:border-box}body{margin:0;background:#f5f6f8;color:#18202c;font-family:Onest,Arial,sans-serif}header{height:80px;padding:20px 30px;border-bottom:1px solid #d9dfe8;display:flex;align-items:center;justify-content:space-between;background:white}header strong{font-size:22px;letter-spacing:-.5px}header img{width:36px;vertical-align:middle;margin-right:12px}header .sub{font-size:13px;color:#637082;margin-left:16px}.layout{display:grid;grid-template-columns:240px 1fr;min-height:calc(100vh - 80px)}nav{padding:24px 14px;background:#18202c;color:white}.nav-item{display:block;width:100%;text-align:left;border:0;background:transparent;color:#bac4d2;font:500 14px Onest,Arial;padding:16px 12px;cursor:pointer;border-radius:7px}.nav-item span{margin-right:13px;color:#7f8da1}.nav-item.active{background:#347bcd;color:white}.nav-item.active span{color:white}.nav-note{font-size:12px;line-height:1.6;color:#bac4d2;margin:25px 12px}main{padding:30px 40px 20px;max-width:1500px;width:100%;margin:auto}.eyebrow{font-size:12px;letter-spacing:1.5px;color:#4c6c92;font-weight:700}h1{font-size:clamp(28px,3.1vw,46px);letter-spacing:-1.5px;line-height:1.12;margin:12px 0 26px}h2{font-size:21px;margin:0 0 15px;letter-spacing:-.5px}p,li{font-size:16px;line-height:1.55}li{margin-bottom:10px}a{color:#195caa;font-size:14px;font-weight:600;text-decoration:none}a:hover{text-decoration:underline}blockquote{font-size:clamp(24px,3vw,42px);font-weight:600;letter-spacing:-1px;line-height:1.35;border-left:5px solid #347bcd;background:white;margin:10px 0;padding:28px 32px}.lead{font-size:21px;color:#465468;max-width:860px}.small{font-size:13px;color:#637082}.chips{display:flex;gap:10px;flex-wrap:wrap;margin:22px 0}.chips span{background:#e5edf7;color:#335779;padding:8px 12px;font-size:13px;border-radius:5px}.grid{display:grid;gap:22px}.two{grid-template-columns:1fr 1fr}.three{grid-template-columns:repeat(3,1fr)}article{padding:22px;background:white;border:1px solid #dbe1e9;border-radius:10px}video{width:100%;max-height:32vh;background:#18202c;border-radius:4px}.final{display:block;max-height:54vh;aspect-ratio:16/9;width:auto;max-width:100%;margin:auto}figure{margin:8px 0 12px}figure img{width:100%;max-height:19vh;object-fit:contain;background:#18202c}figcaption{font-size:12px;color:#637082;margin-top:5px}.say{display:flex;gap:16px;border-top:1px solid #d3dce7;margin-top:25px;padding-top:18px;color:#42546c;font-size:15px;line-height:1.5}.say b{color:#347bcd;font-size:11px;letter-spacing:1.5px;padding-top:3px}table{width:100%;border-collapse:collapse;background:white}td,th{padding:18px 20px;text-align:left;border-bottom:1px solid #dbe1e9;font-size:15px}th{color:#60718a;font-size:12px;text-transform:uppercase}td:first-child{font-weight:700;white-space:nowrap}.mono,pre{font-family:ui-monospace,Menlo,monospace}pre{font-size:12px;line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere;background:#eef2f7;padding:15px;max-height:350px;overflow:auto}.failed,.passed{padding:14px;border-radius:6px;margin:10px 0;font-size:14px}.failed{background:#fff0ed;color:#863b2b}.passed{background:#eaf5ee;color:#246741}.failed p,.passed p{font-size:13px;margin:8px 0 0}.controls{display:flex;justify-content:space-between;align-items:center;margin-top:24px}.controls button,.excerpt{border:1px solid #bdccdf;border-radius:6px;background:white;padding:10px 16px;color:#244b7a;cursor:pointer;font:500 13px Onest}#counter{font-size:12px;color:#6d798a}#timer{font-variant-numeric:tabular-nums;border:1px solid #d3dce7;border-radius:5px;padding:9px 14px;background:#f5f6f8;cursor:pointer;color:#335779}.stage[hidden]{display:none}@media(max-width:850px){.layout{grid-template-columns:1fr}nav{display:flex;overflow:auto;padding:8px}.nav-item{white-space:nowrap;width:auto}.nav-note{display:none}main{padding:20px}.three,.two{grid-template-columns:1fr}header .sub{display:none}video{max-height:45vh}}
</style></head><body><header><div><img src="assets/kite-slack-app-icon.png" alt="Kite"><strong>Kite / core workflow</strong><span class="sub">Actual run · 23 September 2026</span></div><button id="timer">Start 5:00 rehearsal</button></header><div class="layout"><nav>'''+nav+'''<p class="nav-note">4:40 walkthrough<br>0:20 buffer<br><br>Use ← → to advance.<br>No new generation required.</p></nav><main>'''+''.join(sections)+'''<div class="controls"><button id="previous">← Previous</button><span id="counter">1 / 8</span><button id="next">Next →</button></div></main></div><script>
let current=1;function show(n){current=Math.max(1,Math.min(8,n));document.querySelectorAll('video').forEach(v=>v.pause());document.querySelectorAll('.stage').forEach((s,i)=>s.hidden=i+1!==current);document.querySelectorAll('.nav-item').forEach((b,i)=>b.classList.toggle('active',i+1===current));document.getElementById('counter').textContent=current+' / 8';history.replaceState(null,'','#stage-'+current);window.scrollTo(0,0)}document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>show(+b.dataset.stage));document.getElementById('previous').onclick=()=>show(current-1);document.getElementById('next').onclick=()=>show(current+1);document.addEventListener('keydown',e=>{if(e.target.tagName==='VIDEO')return;if(e.key==='ArrowRight')show(current+1);if(e.key==='ArrowLeft')show(current-1)});document.querySelectorAll('.excerpt').forEach(b=>b.onclick=()=>{const v=document.getElementById(b.dataset.video);v.currentTime=+b.dataset.start;v.dataset.end=b.dataset.end;v.play()});document.querySelectorAll('.ref video').forEach(v=>v.addEventListener('timeupdate',()=>{if(v.dataset.end&&v.currentTime>=+v.dataset.end){v.pause();delete v.dataset.end}}));let timerId;document.getElementById('timer').onclick=()=>{clearInterval(timerId);const end=Date.now()+300000;timerId=setInterval(()=>{const s=Math.max(0,Math.ceil((end-Date.now())/1000));document.getElementById('timer').textContent=Math.floor(s/60)+':'+String(s%60).padStart(2,'0')+' remaining';if(!s)clearInterval(timerId)},200)};const start=location.hash.match(/stage-([0-9])/);if(start)show(+start[1]);
</script></body></html>'''
(P/'DEMO.html').write_text(page)
print(P/'DEMO.html')
